private function bcRoundHalfUp(string $value, int $precision): string
{
    $multiplier = bcpow('10', (string)($precision + 1));
    $shifted = bcmul($value, $multiplier, 0);

    // Get the last digit for rounding
    $lastDigit = (int)substr($shifted, -1);

    $truncated = bcdiv($shifted, '10', 0);

    if ($lastDigit >= 5) {
        if (bccomp($value, '0', 16) >= 0) {
            $truncated = bcadd($truncated, '1', 0);
        } else {
            $truncated = bcsub($truncated, '1', 0);
        }
    }

    // Move decimal point back
    $divisor = bcpow('10', (string)$precision);
    return bcdiv($truncated, $divisor, $precision);
}

