protected function execute(InputInterface $input, OutputInterface $output): int
{
    $from = $input->getOption('from') ? new \DateTimeImmutable($input->getOption('from')) : null;
    $to = $input->getOption('to') ? new \DateTimeImmutable($input->getOption('to')) : null;

    $queryBuilder = $this->entityManager->createQueryBuilder()
        ->select('u.user, m.provider, m.code')
        ->from(UsageEvent::class, 'u')
        ->join('u.model', 'm')
        ->where('u.costUsd IS NOT NULL');

    if ($from) {
        $queryBuilder->andWhere('u.ts >= :from')->setParameter('from', $from);
    }
    if ($to) {
        $queryBuilder->andWhere('u.ts < :to')->setParameter('to', $to);
    }

    $groups = $queryBuilder->getQuery()->getResult();

    // To avoid multiple queries, we can just fetch all events in the range
    // but that might be too many. Let's use aggregation.

    $reportQueryBuilder = $this->entityManager->createQueryBuilder()
        ->select('u.user, m.provider, m.code, 
                 SUM(u.tokensInput) as totalInput, 
                 SUM(u.tokensOutput) as totalOutput, 
                 SUM(u.tokensCacheRead) as totalCacheRead, 
                 SUM(u.tokensCacheWrite) as totalCacheWrite, 
                 SUM(CAST(u.costUsd AS decimal)) as totalCost')
        ->from(UsageEvent::class, 'u')
        ->join('u.model', 'm')
        ->where('u.costUsd IS NOT NULL');

    if ($from) {
        $reportQueryBuilder->andWhere('u.ts >= :from')->setParameter('from', $from);
    }
    if ($to) {
        $reportQueryBuilder->andWhere('u.ts < :to')->setParameter('to', $to);
    }

    $reportQueryBuilder->groupBy('u.user, m.provider, m.code')
        ->orderBy('u.user', 'ASC')
        ->addOrderBy('m.provider', 'ASC')
        ->addOrderBy('m.code', 'ASC');

    $results = $reportQueryBuilder->getQuery()->getResult();

    $output->writeln('user,model,tokens_input,tokens_output,tokens_cache_read,tokens_cache_write,cost_usd');

    $totalInput = 0;
    $totalOutput = 0;
    $totalCacheRead = 0;
    $totalCacheWrite = 0;
    $totalCost = '0';

    foreach ($results as $row) {
        $modelName = $row['provider']->getCode() . '/' . $row['code'];
        $cost = number_format((float)$row['totalCost'], 6, '.', '');

        $output->writeln(sprintf(
            '%s,%s,%d,%d,%d,%d,%s',
            $row['user'],
            $modelName,
            $row['totalInput'],
            $row['totalOutput'],
            $row['totalCacheRead'],
            $row['totalCacheWrite'],
            $cost
        ));

        $totalInput += $row['totalInput'];
        $totalOutput += $row['totalOutput'];
        $totalCacheRead += $row['totalCacheRead'];
        $totalCacheWrite += $row['totalCacheWrite'];
        $totalCost = bcadd($totalCost, (string)$row['totalCost'], 6);
    }

    $output->writeln(sprintf(
        'TOTAL,,%d,%d,%d,%d,%s',
        $totalInput,
        $totalOutput,
        $totalCacheRead,
        $totalCacheWrite,
        number_format((float)$totalCost, 6, '.', '')
    ));

    return Command::SUCCESS;
}

